/**
 * World land outline for the seller dashboard Live map, as one SVG path in
 * a flat equirectangular projection (react-native-svg renders it).
 *
 * GENERATED FILE, do not edit by hand. Source: Natural Earth 1:110m land
 * (public domain, https://www.naturalearthdata.com/) via the npm package
 * world-atlas@2.0.2 (land-110m.json, ISC). A throwaway script outside the
 * repo ran topojson-client@3.1.0 feature() and topojson-simplify@3.0.3
 * presimplify()/simplify(quantile 0.3), dropped Antarctica and slivers
 * under 2 square units, and wrote integer coordinates on a 0.5 degree grid:
 *   x = (lng + 180) * 2,  y = (84 - lat) * 2   (lat clamped to [-58, 84])
 * so the view box is 720 x 284.
 */
export const WORLD_VIEWBOX = { width: 720, height: 284 } as const;
export const WORLD_LAT_TOP = 84;
export const WORLD_LAT_BOTTOM = -58;

/** Projects a point to view-box coordinates (same projection as WORLD_LAND_PATH). */
export function projectLatLng(lat: number, lng: number): { x: number; y: number } {
  const clamped = Math.max(WORLD_LAT_BOTTOM, Math.min(WORLD_LAT_TOP, lat));
  return { x: (lng + 180) * 2, y: (WORLD_LAT_TOP - clamped) * 2 };
}

